import json
import sqlite3


def q588(path, dependencies):
    names = set(dependencies)
    pending = set(names)
    done = set()
    while pending:
        ready = {n for n in pending if set(dependencies[n]) <= done}
        if not ready:
            raise ValueError("cycle or missing dependency")
        done |= ready
        pending -= ready
    config = json.dumps(
        {k: sorted(v) for k, v in dependencies.items()}, sort_keys=True
    )

    class Store:

        def __init__(self):
            self.db = sqlite3.connect(path)
            with self.db:
                self.db.execute(
                    "CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT)"
                )
                self.db.execute(
                    "CREATE TABLE IF NOT EXISTS nodes (id TEXT PRIMARY KEY,state TEXT,attempts INTEGER)"
                )
                old = self.db.execute(
                    "SELECT value FROM metadata WHERE key=?", ("schema1",)
                ).fetchone()
                if old and old[0] != config:
                    raise ValueError("workflow configuration mismatch")
                self.db.execute(
                    "INSERT OR IGNORE INTO metadata VALUES (?,?)",
                    ("schema1", config),
                )
                self.db.executemany(
                    "INSERT OR IGNORE INTO nodes VALUES (?, ?, ?)",
                    [(n, "pending", 0) for n in names],
                )

        def states(self):
            return {
                n: (s, a)
                for n, s, a in self.db.execute(
                    "SELECT id,state,attempts FROM nodes"
                )
            }

        def claim(self):
            with self.db:
                self.db.execute("BEGIN IMMEDIATE")
                state = self.states()
                for n in sorted(names):
                    if state[n][0] == "pending" and all(
                        (
                            state[d][0] == "succeeded"
                            for d in dependencies[n]
                        )
                    ):
                        self.db.execute(
                            "UPDATE nodes SET state='running',attempts=attempts+1 WHERE id=?",
                            (n,),
                        )
                        return n
            return None

        def finish(self, node, success):
            with self.db:
                cursor = self.db.execute(
                    "UPDATE nodes SET state=? WHERE id=? AND state='running'",
                    ("succeeded" if success else "failed", node),
                )
                if cursor.rowcount != 1:
                    raise ValueError("node not running")

        def recover(self):
            with self.db:
                self.db.execute(
                    "UPDATE nodes SET state='pending' WHERE state='running'"
                )

        def close(self):
            self.db.close()

    return Store()
